function [T_measure,I]=get_output_current_shape(data,meas_sipm_par,fixed_sipm_par,point_number)
    
    % VM: This function gets the output current of SiPM
    %     It creates a vector of times logarithmically distributed and
    %     evaluates the current created by each succesfull event at at time
    %     
    %     As input parameters it needs the data struct generated by
    %     sipm_sim_array.m, meas_sipm_par and fixed_sipm_par struct generated by
    %     read_input_array.m and the number of elements in the output
    %     vectors point_number
    %
    %     As output parameters it generates a vector I with the total output
    %     current evaluated in the times corresponding to the T_measure
    %     vector

    % VM: Calculation of needed constants

    charge_elec= 1.6e-19;
    Cd =  meas_sipm_par.Cd_mean;
    Cq = meas_sipm_par.Cq_mean;
    G=(Cd+Cq)*meas_sipm_par.V_ob_mean/charge_elec;
    trec=charge_elec*G*meas_sipm_par.Rq_mean/meas_sipm_par.V_ob_mean;
    
    % VM: Creation of the time vector and its corresponding current vector

    T_measure=logspace(log10(0.01*trec),log10(fixed_sipm_par.tmeas),point_number)';
    I=zeros(point_number,1);

    % VM: Calculation of the initial current per succesful event and each
    %     corresponding time

    time=data.t;
    gain=data.gain;
    I_instant=gain(data.gain>0)*meas_sipm_par.V_ob_mean/meas_sipm_par.Rq_mean;
    T=time(data.gain>0);


    % VM: Evaluation of the total output current by adding the current of each event at T_measure times

    for i=1:length(I)
        for j=1:length(I_instant)
            I(i)=I(i)+ instant_current(T_measure(i),T(j),I_instant(j),trec);
        end
    end

